layer.css:
[data-ryt="footer"] { color: var(--ryt-text); border-top: 1px solid rgba(206, 216, 216, 0.102); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { background-color: rgba(30, 42, 58, 0.502); background-image: linear-gradient(rgba(255, 255, 255, 0.016), rgba(255, 255, 255, 0.004)); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-top: 1px solid color-mix(in srgb, var(--ryt-border) 3%, transparent); border-right: 1px solid color-mix(in srgb, var(--ryt-border) 3%, transparent); border-bottom: 1px solid color-mix(in srgb, var(--ryt-border) 3%, transparent); border-left: 4px solid rgba(30, 40, 56, 0.302); border-radius: 12px; box-shadow: rgba(3, 6, 22, 0.45) 0px 10px 22px 0px; transition: transform 0.26s cubic-bezier(0.2, 0.9, 0.3, 1), box-shadow 0.26s cubic-bezier(0.2, 0.9, 0.3, 1) }
[data-ryt="nav"] a { color: var(--ryt-accent); border-radius: 8px; font-family: "crimson pro"; font-size: 20px; font-weight: 300; font-style: normal; line-height: 1.333; letter-spacing: 0.4px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 12px; padding-right: 24px; padding-bottom: 12px; padding-left: 24px; transition: color 0.22s, background-color 0.22s, transform 0.22s }
[data-ryt="button"] { color: rgb(209, 213, 220); background-color: rgb(231, 0, 11); border-radius: 3.35544e+07px; font-family: "crimson pro"; font-weight: 100; font-style: normal; line-height: 1.333; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(209, 213, 220); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 8px; padding-right: 0px; padding-bottom: 8px; padding-left: 0px; transition: all }
[data-ryt="review"] { color: rgb(106, 114, 130); font-family: "crimson pro"; font-size: 20px; font-weight: 300; font-style: normal; line-height: 1.8; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(106, 114, 130); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="cover"] { border-radius: 12px }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-accent); border-radius: 0px; font-family: "crimson pro"; font-weight: 500; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.18s, text-shadow 0.18s; padding-bottom: 6px; position: relative }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: "crimson pro"; font-size: 24px; font-weight: 500; font-style: normal; line-height: 1.667; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a::after { content: ""; display: block; position: absolute; height: 2px; color: var(--ryt-accent); background-image: linear-gradient(90deg, rgb(251, 44, 54), rgba(252, 43, 53, 0.6)); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 2px; font-family: "crimson pro"; font-size: 24px; font-weight: 500; font-style: normal; line-height: 1.667; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: width 0.26s cubic-bezier(0.2, 0.9, 0.2, 1); -webkit-text-fill-color: var(--ryt-accent); bottom: -6px; left: 0px }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: rgb(209, 213, 220); text-shadow: rgba(217, 70, 70, 0.08) 0px 6px 18px }
[data-ryt="cover"]:hover { transform: scale(1.06); filter: brightness(0.95) saturate(1.05) }
[data-ryt="nav"] a:hover { color: rgb(209, 213, 220); background-color: color-mix(in oklab,var(--ryt-accent) 8%,transparent); transform: translateY(-2px); text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
article[data-ryt="rec-card"]:hover { transform: translateY(-6px) scale(1.01); box-shadow: rgba(2, 6, 23, 0.6) 0px 20px 40px }
